using var deadline = new CancellationTokenSource();
deadline.CancelAfter(TimeSpan.FromMilliseconds(700));
using var operation = CancellationTokenSource.CreateLinkedTokenSource(
    serviceStoppingToken, deadline.Token);

try
{
    await SendCompleteRequestAsync(socket, payload, operation.Token);
    return await WaitForReplyAsync(requestId, operation.Token);
}
catch (OperationCanceledException) when (
    deadline.IsCancellationRequested && !serviceStoppingToken.IsCancellationRequested)
{
    return RequestOutcome.Unknown; // 應用型別：傳送後無回覆，遠端結果未知
}

static async Task<int> ReadWithExternalTimeoutAsync(
    Socket socket, Memory<byte> buffer)
{
    Task<int> pending = socket.ReceiveAsync(
        buffer, SocketFlags.None, CancellationToken.None).AsTask();
    return await pending.WaitAsync(TimeSpan.FromMilliseconds(500));
}
